using Noir;
public static class PremiumChecks {
 public static void Run(string root,Action<bool,string> check){
 var directory=Path.Combine(root,"premium-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);var store=new LibraryStore(directory);
 var path=Path.Combine(directory,"Episode.S01E01.mkv");File.WriteAllBytes(path,[1,2,3]);var item=new VideoItem{Path=path,Title="Episode",Season=1,Episode=1};store.Record(item,42.125,1200);item=store.Archive.Single();var id=item.Id;var key=item.GroupKey;
 store.Mark(item,true);var viewing=store.ViewingHistory(item).Single().Id;store.SetStatus(item,"Dropped");store.SetCollection(item,"Favorites",true);store.Queue(item);store.Queue(item);
 var reopened=new LibraryStore(directory);item=reopened.Archive.Single();check(reopened.State.PlayQueue.Count==1&&reopened.TitleStatus([item])=="Dropped"&&reopened.State.Collections["Favorites"].Contains(key),"Statuses, collections and deduplicated play queue survive restart");
 reopened.CorrectMatch(item,"Correct title",2024,"tt1234567",2,1,true);reopened.State.Roots=[new(){Path=directory}];var scanned=reopened.Scan(out _).Single();check(scanned.Id==id&&scanned.GroupKey==key&&scanned.Title=="Correct title"&&scanned.Season==2&&reopened.ViewingHistory(scanned).Single().Id==viewing,"Match corrections survive scanning without changing file identity or watch history");
 check(reopened.QueuedNext(new VideoItem{Id="other"},[scanned])?.Id==id,"Queue selects the next available saved item");File.Delete(path);check(reopened.QueuedNext(new VideoItem{Id="other"},[scanned])==null&&reopened.State.PlayQueue.Count==1,"Unavailable queued files are skipped without deleting the queue");
 var at=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()+5;var add=new MobileOperation{Id=Guid.NewGuid().ToString(),ItemId=id,Kind="collection",Name="Phone picks",Value=true,At=at};var drop=new MobileOperation{Id=Guid.NewGuid().ToString(),ItemId=id,Kind="status",Status="Watching",At=at};reopened.MergeMobile([add,drop]);reopened.MergeMobile([new(){Id=Guid.NewGuid().ToString(),ItemId=id,Kind="status",Status="Dropped",At=at-1}]);
 var snapshot=reopened.MobileSnapshot();check(snapshot.Items.Single().Status=="Watching"&&snapshot.Items.Single().Collections.Contains("Phone picks")&&snapshot.Collections.Contains("Phone picks"),"Phone status and collection operations sync with field clocks rejecting stale changes");
 check(reopened.ViewingHistory(scanned).Single().Id==viewing&&snapshot.Items.Single().Available==false,"Organization changes and missing files preserve viewing records");
 check(ReviewLinks.TopDiscussion("https://old.reddit.com/r/tv/comments/abc123/title/comment42/?context=3")=="https://www.reddit.com/r/tv/comments/abc123/title/comment42/?sort=top","Top discussion links preserve selected comments and remove tracking parameters");
 var picture=Path.Combine(directory,"cached.jpg");File.WriteAllBytes(picture,[1]);reopened.State.EpisodeSchedules[key]=[new(){Season=2,Episode=2,Title="Known missing episode",Image=picture,AirsAt=DateTimeOffset.UtcNow.AddDays(-1)}];var virtualItem=reopened.EpisodesFor(key).Single(i=>i.Episode==2);reopened.Mark(virtualItem,true);
 var remembered=reopened.Archive.Single(i=>i.Id==virtualItem.Id);check(remembered.ImdbId=="tt1234567"&&remembered.EpisodeImage==picture&&reopened.EverWatched(remembered),"Watching a missing known episode preserves its match and cached artwork");
 var projected=System.Text.Json.JsonSerializer.Serialize(reopened.MobileSnapshot());check(!projected.Contains(directory.Replace("\\","\\\\")),"Phone episode schedules never reveal PC artwork paths");
 var stale=new MobileOperation{Id=Guid.NewGuid().ToString(),ItemId=id,Kind="match",Title="Wrong older title",Year=2020,Season=2,Episode=1,At=DateTimeOffset.UtcNow.AddDays(-1).ToUnixTimeMilliseconds()};reopened.MergeMobile([stale]);check(reopened.Archive.First(i=>i.Id==id).Title=="Correct title","An older phone match correction cannot replace a newer PC correction");
 }
}
